:root {
  --pixel-border: #1a1a1a;
  --accent: #ff6b6b;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #7a8cff;
  font-family: 'Courier New', monospace;
  image-rendering: pixelated;
}
.calculator {
  background: #f5f5f5;
  padding: 2rem;
  border: 6px solid var(--pixel-border);
  box-shadow: 10px 10px 0 #000;
  width: min(90%, 360px);
}
h1 {
  text-align: center;
  font-size: 1.8rem;
  margin-top: 0;
  letter-spacing: 4px;
  text-shadow: 3px 3px 0 #ff6b6b;
}
.field { margin-bottom: 1rem; }
label { display: block; margin-bottom: 0.25rem; font-weight: bold; }
input, select, button {
  width: 100%;
  padding: 0.6rem;
  font: inherit;
  border: 3px solid var(--pixel-border);
  background: #fff;
  box-shadow: 4px 4px 0 #000;
  border-radius: 0;
  outline: none;
}
input:focus, select:focus, button:focus {
  outline: 3px dashed #fff;
  outline-offset: 2px;
  background: #fffeca;
}
button {
  margin-top: 0.5rem;
  cursor: pointer;
  background: var(--accent);
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 2px;
}
.result-panel {
  margin-top: 1.5rem;
  background: #111;
  padding: 0.75rem;
  border: 3px solid var(--pixel-border);
  box-shadow: inset 4px 4px 0 #000;
}
output {
  display: block;
  min-height: 2.5rem;
  color: #0f0;
  text-align: right;
  font-size: 1.6rem;
  font-weight: bold;
  overflow-wrap: anywhere;
  background: #222;
  padding: 0.5rem;
  border: 2px solid #0f0;
}

'use strict';

const leftInput = document.getElementById('left');
const rightInput = document.getElementById('right');
const operationSelect = document.getElementById('operation');
const calculateButton = document.getElementById('calculate');
const resultOutput = document.getElementById('result');

function readNumber(input) {
  if (input.value.trim() === '') return null;
  const number = Number(input.value);
  return Number.isFinite(number) ? number : null;
}

function setError() {
  resultOutput.textContent = 'Error';
}

calculateButton.addEventListener('click', () => {
  const left = readNumber(leftInput);
  const right = readNumber(rightInput);

  if (left === null || right === null) {
    setError();
    return;
  }

  let result;
  switch (operationSelect.value) {
    case 'add':
      result = left + right;
      break;
    case 'subtract':
      result = left - right;
      break;
    case 'multiply':
      result = left * right;
      break;
    case 'divide':
      if (right === 0) {
        setError();
        return;
      }
      result = left / right;
      break;
    default:
      setError();
      return;
  }

  if (!Number.isFinite(result)) {
    setError();
    return;
  }

  resultOutput.textContent = String(result);
});
